mod solution;

fn valid(_input: &str, actual: &str, expected: &str) -> bool { actual == expected }

fn main() {
    let cases = [
        ("values=[5,4,7,2] update=(2,0) query=1..3","0"),
        ("values=[9,5,7] update=(1,6) query=0..2","6"),
        ("values=[1,2,3] update=(0,9) query=0..2","2"),
        ("values=[4,4,4,4] update=(3,1) query=1..3","1"),
        ("values=[8,6,7] update=(1,2) query=0..0","8"),
        ("  \nvalues=[5,4,7,2] update=(2,0) query=1..3\n  ","0"),
        ("\nvalues=[8,6,7] update=(1,2) query=0..0\n","8")
    ];
    for (i,(input,expected)) in cases.iter().enumerate() {
        let actual = solution::solve(input);
        if !valid(input,&actual,expected) { eprintln!("PRIVATE CASE {} FAILED",i+1); std::process::exit(1); }
    }
    println!("PASS segment-tree");
}
